export function attachSurveyMap({$,state,auth,config,onFeature}){let map=null,base=null,drawn=[],focus=null,serial=0,busy=false,started=false,account=null,debounce=null;const status=t=>$('survey-map-status').textContent=t;
 const css=document.createElement('link');css.rel='stylesheet';css.href=new URL('./vendor/leaflet.css',import.meta.url);document.head.append(css);
 function init(){if(map)return;map=L.map($('survey-map'),{preferCanvas:true}).setView([-1.94,29.87],9);map.attributionControl.setPrefix('Leaflet');base=L.tileLayer('https://services.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:20,maxNativeZoom:19,attribution:'Imagery © Esri, Vantor, Earthstar Geographics and the GIS User Community',referrerPolicy:'no-referrer'}).addTo(map);base.on('tileerror',()=>{$('survey-map-base-status').textContent='Some basemap tiles could not load. Survey features remain available.';});map.on('moveend',()=>{if(started&&$('survey-map-auto').checked){clearTimeout(debounce);debounce=setTimeout(()=>load(false),700);}});$('survey-map-basemap').onchange=()=>{if($('survey-map-basemap').value==='none'){map.removeLayer(base);$('survey-map-base-status').textContent='Basemap hidden.';}else{base.addTo(map);$('survey-map-base-status').textContent='Satellite basemap: Esri World Imagery.';}};}
 function clear(){serial++;started=false;account=null;clearTimeout(debounce);if(map){for(const layer of drawn)map.removeLayer(layer);if(focus)map.removeLayer(focus);}drawn=[];focus=null;$('survey-map-selected').textContent='';$('survey-map-layers').replaceChildren();status('Selections changed. Load / refresh surveyed data to use the current layers, usernames and boundaries.');}
 function draw(shape,style){return shape.kind==='point'?L.circleMarker(shape.coordinates,{radius:5,...style}):shape.kind==='line'?L.polyline(shape.coordinates,style):L.polygon(shape.coordinates,style);}
 function record(layer,feature){const a=feature.attributes,fields=layer.fields.map(n=>layer.meta.fields.find(f=>f.name===n)).filter(Boolean),checked=checkedAttributes(layer.meta,a,fields),gid=globalIdField(layer.meta);return {key:JSON.stringify([layer.url,a[layer.meta.objectIdField],a[layer.source]]),layer:layer.meta.name,url:layer.url,id:a[gid?.name]||a[layer.meta.objectIdField],objectId:a[layer.meta.objectIdField],globalId:gid?a[gid.name]:null,globalIdField:gid?.name,user:a[layer.source]||'No tracking username',checkedAttributes:checked,fields:checked.filter(f=>f.kind).map(f=>f.name),missingFields:checked.filter(f=>f.kind).map(f=>({...f})),...timeInfo(layer.meta,a,layer.collected,Date.now())};}
 async function load(fit=false){if(busy){status('Map is loading. Refresh again when it finishes.');return;}busy=true;let version;try{init();const api=auth(),selection=await config();version=++serial;if(!selection.layers.length)throw Error('Choose monitoring layers first.');account=api;started=false;if(fit&&selection.geometry){const parts=selection.geometry.parts||[selection.geometry],rings=parts.flatMap(g=>g.rings);const points=rings.flat().map(p=>[p[1],p[0]]);map.fitBounds(L.latLngBounds(points),{padding:[18,18],maxZoom:16});}map.invalidateSize();status('Loading surveyed features in the visible map area…');const b=map.getBounds(),bounds={xmin:b.getWest(),ymin:b.getSouth(),xmax:b.getEast(),ymax:b.getNorth()},groups=[],notes=[];let count=0,missing=0,limited=false;
 for(const layer of selection.layers){try{const data=await mapLayerRecords(api,layer,bounds,selection.spatial,selection.users);if(serial!==version||auth()!==api)return;const group=L.featureGroup();for(const feature of data.rows){const issue=record(layer,feature);issue.boundary=selection.label;const incomplete=issue.fields.length>0;count++;if(incomplete)missing++;const color=incomplete?'#ff3030':feature.shape.kind==='line'?'#27d8ff':layer.space==='Structure Junction'?'#ffffff':'#ffff00';const item=draw(feature.shape,{color:feature.shape.kind==='point'?'#172d30':color,fillColor:color,fillOpacity:.95,weight:feature.shape.kind==='line'?3:1.5});const box=document.createElement('div'),title=document.createElement('strong'),text=document.createElement('p'),button=document.createElement('button');title.textContent=issue.layer;text.textContent='User: '+issue.user+'\nGlobal ID: '+(issue.globalId||'Not exposed')+'\n'+(fieldsMessage(issue));button.type='button';button.textContent='View attributes and attachments';button.onclick=()=>onFeature(issue);box.append(title,text,button);item.bindPopup(box);group.addLayer(item);}groups.push({layer,group,count:data.rows.length});if(data.limited){limited=true;notes.push(layer.meta.name+': showing the first 10,000 of '+data.total+' matching features; zoom in.');}if(data.problems.length)notes.push(layer.meta.name+': '+data.problems.length+' unreadable/missing geometry record(s).');}catch(e){notes.push(layer.meta.name+': '+e.message);}}
 if(serial!==version||auth()!==api)return;for(const old of drawn)map.removeLayer(old);drawn=[];$('survey-map-layers').replaceChildren();for(const {layer,group,count} of groups){group.addTo(map);drawn.push(group);const label=document.createElement('label'),input=document.createElement('input');label.className='null-toggle';input.type='checkbox';input.checked=true;input.setAttribute('aria-label','Show map layer '+layer.meta.name);input.onchange=()=>input.checked?group.addTo(map):map.removeLayer(group);label.append(input,document.createTextNode(layer.meta.name+' ('+count+')'));$('survey-map-layers').append(label);}started=true;if(!map.getBounds().equals(b)&&$('survey-map-auto').checked){clearTimeout(debounce);debounce=setTimeout(()=>load(false),700);}status(count+' surveyed features shown in this map view; '+missing+' have missing monitored attributes. '+(selection.label?'Boundary: '+selection.label+'. ':'')+(notes.length?'Coverage incomplete / limited: '+notes.join(' '):'All accessible matching IDs in this view were processed.')+' Updated '+new Date().toLocaleTimeString('en-GB',{timeZone:'Africa/Kigali'})+' Kigali.');}catch(e){if(version===undefined||serial===version)status('Map unavailable: '+e.message);}finally{busy=false;}}
 function fieldsMessage(issue){return issue.checkedAttributes.length?(issue.fields.length?'Missing: '+issue.missingFields.map(f=>f.label).join(', '):'All selected monitoring attributes are filled.'):'No attribute rules selected for this layer.';}
 $('survey-map-load').onclick=()=>load(!started);$('survey-map-fit').onclick=()=>load(true);
 return {clear,refresh(){if(started&&$('survey-map-auto').checked)load(false);},checkSession(){if(account){try{if(auth()!==account)clear();}catch{clear();}}},async locate(issue){init();serial++;started=false;const api=auth(),meta=(await config()).layers.find(l=>l.url===issue.url)?.meta;if(!meta)throw Error('Select this alert layer to locate it on the monitor map.');const result=await api.request(issue.url+'/query',{objectIds:issue.objectId,outFields:[meta.objectIdField,issue.globalIdField].filter(Boolean).join(','),returnGeometry:true,outSR:4326});const f=result.features?.find(f=>f.attributes[meta.objectIdField]===issue.objectId);if(!f||!issue.globalIdField||String(f.attributes[issue.globalIdField]).replace(/[{}]/g,'').toLowerCase()!==String(issue.globalId).replace(/[{}]/g,'').toLowerCase())throw Error('Alert Global ID is no longer readable. Run a fresh check.');if(auth()!==api)throw Error('Sign-in changed.');const shape=mapGeometry({...f.geometry,spatialReference:f.geometry?.spatialReference||result.spatialReference});account=api;map.invalidateSize();if(focus)map.removeLayer(focus);focus=draw(shape,{color:'#ff00dd',fillColor:'#ff00dd',fillOpacity:.6,weight:5,radius:10}).addTo(map);if(shape.kind==='point')map.setView(shape.coordinates,18);else map.fitBounds(focus.getBounds(),{padding:[40,40],maxZoom:18});$('survey-map-selected').textContent=issue.layer+' · '+issue.user+' · Global ID '+issue.globalId+' · '+fieldsMessage(issue);status('Alert feature highlighted in magenta. Load / refresh surveyed data to see surrounding selected network features.');$('survey-map-card').scrollIntoView({behavior:'smooth',block:'start'});},};}
